  instagramAccount?: Prisma.InstagramAccountOmit
  instagramConnection?: Prisma.InstagramConnectionOmit
  mediaAsset?: Prisma.MediaAssetOmit
  mediaReference?: Prisma.MediaReferenceOmit
  post?: Prisma.PostOmit
  postMedia?: Prisma.PostMediaOmit
